+import prismaMock from '../prisma-mock';
+import { deleteComment, getCommentsByArticle } from '../../app/routes/article/article.service';
+import HttpException from '../../app/models/http-exception.model';
+
+describe('ArticleService', () => {
+  describe('deleteComment', () => {
+    const commentId = 123;
+    const authorId = 456;
+
+    test('should set deletedAt and keep the row', async () => {
+      // When
+      // @ts-ignore
+      prismaMock.comment.findFirst.mockResolvedValue({
+        author: { id: authorId, username: 'RealWorld' },
+      });
+      // @ts-ignore
+      prismaMock.comment.update.mockResolvedValue({});
+
+      // Then
+      await deleteComment(commentId, authorId);
+
+      expect(prismaMock.comment.update).toHaveBeenCalledWith({
+        where: { id: commentId },
+        data: { deletedAt: expect.any(Date) },
+      });
+      expect(prismaMock.comment.delete).not.toHaveBeenCalled();
+    });
+
+    test('should look the comment up as the author and only when not yet deleted', async () => {
+      // When
+      // @ts-ignore
+      prismaMock.comment.findFirst.mockResolvedValue({
+        author: { id: authorId, username: 'RealWorld' },
+      });
+      // @ts-ignore
+      prismaMock.comment.update.mockResolvedValue({});
+
+      // Then
+      await deleteComment(commentId, authorId);
+
+      expect(prismaMock.comment.findFirst).toHaveBeenCalledWith(
+        expect.objectContaining({
+          where: { id: commentId, deletedAt: null, author: { id: authorId } },
+        }),
+      );
+    });
+
+    test('should return 404 and not update when the comment is not found', async () => {
+      // When
+      // @ts-ignore
+      prismaMock.comment.findFirst.mockResolvedValue(null);
+
+      // Then
+      const attempt = deleteComment(commentId, authorId);
+      await expect(attempt).rejects.toBeInstanceOf(HttpException);
+      await expect(attempt).rejects.toHaveProperty('errorCode', 404);
+      expect(prismaMock.comment.update).not.toHaveBeenCalled();
+    });
+  });
+
+  describe('getCommentsByArticle', () => {
+    const slug = 'How-to-train-your-dragon-1';
+
+    test('should leave out comments that have a deletedAt value', async () => {
+      // When
+      // @ts-ignore
+      prismaMock.article.findUnique.mockResolvedValue({ comments: [] });
+
+      // Then
+      await getCommentsByArticle(slug);
+
+      expect(prismaMock.article.findUnique).toHaveBeenCalledWith(
+        expect.objectContaining({
+          where: { slug },
+          include: {
+            comments: expect.objectContaining({
+              where: expect.objectContaining({ deletedAt: null }),
+            }),
+          },
+        }),
+      );
+    });
+
+    test('should return the comments the query returns', async () => {
+      // When
+      // @ts-ignore
+      prismaMock.article.findUnique.mockResolvedValue({
+        comments: [
+          {
+            id: 1,
+            createdAt: new Date(),
+            updatedAt: new Date(),
+            body: 'Visible comment',
+            author: { username: 'RealWorld', bio: null, image: null, followedBy: [] },
+          },
+        ],
+      });
+
+      // Then
+      const result = await getCommentsByArticle(slug);
+
+      expect(result).toHaveLength(1);
+      expect(result?.[0].body).toBe('Visible comment');
+      expect(result?.[0].author.username).toBe('RealWorld');
+    });
+  });
+});
